package main

import (
	"bufio"
	"fmt"
	"os"
)

const SIZE = 1000002

var (
	s  [SIZE]int
	p  [SIZE]int
	np int
	mn int
)

func sieve() {
	for i := 2; i < SIZE; i++ {
		if s[i] == 0 {
			p[np] = i
			np++
			for j := 2; i*j < SIZE; j++ {
				s[i*j] = 1
			}
		}
	}
}

func maxInt(x, y int) int {
	if x > y {
		return x
	}
	return y
}

func solve(x, l int) {
	lf := -1
	ox := x

	if x < mn {
		mn = x
	}

	if l == 0 {
		return
	}

	for i := 0; p[i]*p[i] <= x; i++ {
		if ox%p[i] == 0 {
			lf = maxInt(lf, p[i])
			for ox%p[i] == 0 {
				ox /= p[i]
			}
		}
	}
	if ox > 1 && ox != x {
		lf = maxInt(lf, ox)
	}

	if lf == -1 {
		return
	}

	if l == 1 {
		x = x - lf + 1
		if x < mn {
			mn = x
		}
		return
	}

	for d := x - lf + 1; d < lf*(x/lf); d++ {
		solve(d, l-1)
	}
}

func main() {
	s[0], s[1] = 1, 1
	sieve()
	mn = int(^uint(0) >> 1)

	reader := bufio.NewReader(os.Stdin)
	var x2 int
	fmt.Fscan(reader, &x2)

	solve(x2, 2)
	fmt.Print(mn)
}
